from fastapi import APIRouter, HTTPException

from ledgerly.credit_notes.models import CreditNote
from ledgerly.db import get_session

router = APIRouter(prefix="/credit-notes", tags=["credit notes"])


@router.get("/{credit_note_id}")
def get_credit_note(credit_note_id: int):
    with get_session() as s:
        cn = s.get(CreditNote, credit_note_id)
        if cn is None:
            raise HTTPException(404, "credit note not found")
        return {"id": cn.id, "number": cn.number, "total": cn.total()}

