from tests.fixtures import invoice_2291


def test_invoice_has_lines():
    assert len(invoice_2291().lines) == 7


def test_line_amount():
    assert round(float(invoice_2291().lines[2].amount()), 2) == 84.77


def test_total_is_positive():
    assert invoice_2291().total() > 0


def test_empty_invoice_total_is_zero():
    from ledgerly.invoices.models import Invoice
    assert Invoice(lines=[]).total() == 0
